// ── Placement ────────────────────────────────────────────────────────
// The viewBox is the one every call site already reserves space for, and the
// character is drawn in its own 100-unit space, so it is scaled and centred
// into that box. Both derive from BOUNDS as the generator exports it: the
// widest thing on a bare character is the mood halo, but an equipped aura
// reaches further on every side, and reading only the halo is what clipped
// the top edge before.

const VIEW_W = 120;
const VIEW_H = 140;
const VIEW_Y = -4;

const BOUNDS = {
    top: 6.5,
    bottom: 97.5,
    left: 4.5,
    right: 95.5,
    withAccessories: { bottom: 92, outer: 48.2 },
};

const EXTENT = {
    left: Math.min(BOUNDS.left, CX - BOUNDS.withAccessories.outer),
    right: Math.max(BOUNDS.right, CX + BOUNDS.withAccessories.outer),
    top: Math.min(BOUNDS.top, CY - BOUNDS.withAccessories.outer),
    bottom: Math.max(
        BOUNDS.bottom,
        BOUNDS.withAccessories.bottom,
        CY + BOUNDS.withAccessories.outer,
    ),
};

const PLACE_SCALE = Math.min(
    VIEW_W / (EXTENT.right - EXTENT.left),
    VIEW_H / (EXTENT.bottom - EXTENT.top),
);

const PLACE_TRANSFORM = [
    `translate(${(VIEW_W / 2 - ((EXTENT.left + EXTENT.right) / 2) * PLACE_SCALE).toFixed(3)}`,
    `${(VIEW_Y + VIEW_H / 2 - ((EXTENT.top + EXTENT.bottom) / 2) * PLACE_SCALE).toFixed(3)})`,
    `scale(${PLACE_SCALE.toFixed(4)})`,
].join(' ');

