// ── Season coverage (Plan tab season summary only) ───────────────────

interface SeasonCoverageConfig {
    angles: number[];
    width: number;
    opacity: number;
    shine?: boolean;
}

const FULL_COVERAGE = {
    angles: [-30, -10, 15, 40, 65, 85],
    width: 3,
    opacity: 0.85,
};

const SEASON_COVERAGE: Record<SeasonPhase, SeasonCoverageConfig> = {
    base: { angles: [20], width: 1.4, opacity: 0.3 },
    build: { angles: [-15, 25, 60], width: 2.2, opacity: 0.55 },
    peak: FULL_COVERAGE,
    taper: { ...FULL_COVERAGE, shine: true },
};

const SEASON_COLORS = ['#8d2c3d', '#d9a53c', '#362a73', '#256f4d', '#6b3fa0'];

// ── Primitives ───────────────────────────────────────────────────────

function Stroke({
    d,
    width = 3.8,
    color = SKY,
}: Readonly<{ d: string; width?: number; color?: string }>) {
    return (
        <path
            d={d}
            fill="none"
            stroke={color}
            strokeWidth={width}
            strokeLinecap="round"
        />
    );
}

function Band({
    y,
    height,
    fill,
}: Readonly<{ y: number; height: number; fill: string }>) {
    return (
        <rect
            x={CX - BODY_R}
            y={y}
            width={BODY_R * 2}
            height={height}
            fill={fill}
        />
    );
}

function Brow({
    x,
    outerY,
    innerY,
    side,
}: Readonly<{ x: number; outerY: number; innerY: number; side: 'l' | 'r' }>) {
    const outerX = side === 'l' ? x - 5.5 : x + 5.5;
    const innerX = side === 'l' ? x + 5.5 : x - 5.5;
    return (
        <Stroke
            d={`M${outerX} ${(EYE_Y + outerY).toFixed(1)} L${innerX} ${(EYE_Y + innerY).toFixed(1)}`}
        />
    );
}

function OpenEye({ x, r }: Readonly<{ x: number; r: number }>) {
    return <circle cx={x} cy={EYE_Y} r={r} fill={SKY} />;
}

function LidEye({ x }: Readonly<{ x: number }>) {
    return <Stroke d={`M${x - 4.2} ${EYE_Y} H${x + 4.2}`} width={4.4} />;
}

function Eyes({ shape }: Readonly<{ shape: EyeShape }>) {
    if (shape === 'wide') {
        return (
            <>
                <OpenEye x={EYE_L} r={5.3} />
                <OpenEye x={EYE_R} r={5.3} />
            </>
        );
    }
    if (shape === 'lid') {
        return (
            <>
                <LidEye x={EYE_L} />
                <LidEye x={EYE_R} />
            </>
        );
    }
    if (shape === 'wink-r') {
        return (
            <>
                <OpenEye x={EYE_L} r={4.4} />
                <LidEye x={EYE_R} />
            </>
        );
    }
    return (
        <>
            <OpenEye x={EYE_L} r={4.4} />
            <OpenEye x={EYE_R} r={4.4} />
        </>
    );
}

function Mouth({ shape }: Readonly<{ shape: MouthShape }>) {
    switch (shape) {
        case 'smile-md':
            return (
                <Stroke
                    d={`M${CX - 8} ${EYE_Y + 12.5} Q${CX} ${EYE_Y + 19} ${CX + 8} ${EYE_Y + 12.5}`}
                />
            );
        case 'flat':
            return <Stroke d={`M${CX - 6.5} ${EYE_Y + 13.5} H${CX + 6.5}`} />;
        case 'wry':
            return (
                <Stroke
                    d={`M${CX - 6} ${EYE_Y + 14} Q${CX + 1} ${EYE_Y + 11.5} ${CX + 7} ${EYE_Y + 13.5}`}
                />
            );
        case 'smirk':
            return (
                <Stroke
                    d={`M${CX - 6} ${EYE_Y + 14} Q${CX + 2} ${EYE_Y + 17.5} ${CX + 8} ${EYE_Y + 11.5}`}
                />
            );
        case 'frown-sm':
            return (
                <Stroke
                    d={`M${CX - 6.5} ${EYE_Y + 15.5} Q${CX} ${EYE_Y + 11.5} ${CX + 6.5} ${EYE_Y + 15.5}`}
                />
            );
        case 'frown-md':
            return (
                <Stroke
                    d={`M${CX - 7.5} ${EYE_Y + 16.5} Q${CX} ${EYE_Y + 10.5} ${CX + 7.5} ${EYE_Y + 16.5}`}
                />
            );
        case 'o':
            return (
                <ellipse
                    cx={CX}
                    cy={EYE_Y + 12.5}
                    rx={4}
                    ry={5}
                    fill={SKY}
                    data-mouth="o"
                />
            );
        case 'open':
            return (
                <path
                    d={`M${CX - 8} ${EYE_Y + 11} Q${CX} ${EYE_Y + 21.5} ${CX + 8} ${EYE_Y + 11} Z`}
                    fill={SKY}
                    data-mouth="open"
                />
            );
        default:
            return (
                <Stroke
                    d={`M${CX - 7} ${EYE_Y + 13} Q${CX} ${EYE_Y + 17} ${CX + 7} ${EYE_Y + 13}`}
                />
            );
    }
}

function Detail({ kind }: Readonly<{ kind: DetailKind }>) {
    switch (kind) {
        case 'sunrise':
            return (
                <Stroke
                    d={`M${CX - 9} 72.5 a9 9 0 0 1 18 0`}
                    width={2.2}
                    color={CREAM}
                />
            );
        case 'rain':
            return (
                <Stroke
                    d={`M${CX - 10} 70.5 v3 M${CX} 70 v4 M${CX + 10} 70.5 v3`}
                    width={2}
                    color={CREAM}
                />
            );
        case 'splitPanel':
            return (
                <rect
                    x={CX}
                    y={75}
                    width={31}
                    height={7}
                    fill={CREAM}
                    opacity={0.34}
                />
            );
        case 'speedStripe':
            return (
                <Stroke
                    d={`M${CX - 18} 87 h8 M${CX + 10} 87 h8`}
                    width={2}
                    color={CREAM}
                />
            );
        case 'lugs':
            return (
                <Stroke
                    d={`M${CX - 18} 90 v2 M${CX - 14} 90.5 v2 M${CX - 10} 90 v2 M${CX + 10} 90 v2 M${CX + 14} 90.5 v2 M${CX + 18} 90 v2`}
                    width={1.6}
                    color={INK}
                />
            );
        case 'medalStar':
            return <circle cx={CX} cy={85} r={2.6} fill={SKY} opacity={0.55} />;
        case 'medalRing':
            return (
                <circle
                    cx={CX}
                    cy={85}
                    r={3.4}
                    fill="none"
                    stroke={SKY}
                    strokeWidth={1.3}
                    opacity={0.5}
                />
            );
        default:
            return <circle cx={CX} cy={26} r={2.4} fill={CREAM} />;
    }
}

// ── Slot art ─────────────────────────────────────────────────────────

function Headband({ item }: Readonly<{ item: ItemSpec }>) {
    return (
        <>
            <Band y={23} height={6} fill={item.color} />
            {item.detail !== undefined && <Detail kind={item.detail} />}
        </>
    );
}

function Shirt({ item }: Readonly<{ item: ItemSpec }>) {
    return (
        <>
            <Band y={69} height={6} fill={item.color} />
            <path
                d={`M${CX - 4.5} 69 L${CX} 73 L${CX + 4.5} 69 Z`}
                fill={CREAM}
            />
            {item.detail !== undefined && <Detail kind={item.detail} />}
        </>
    );
}

function Shorts({ item }: Readonly<{ item: ItemSpec }>) {
    return (
        <>
            <Band y={75} height={7} fill={item.color} />
            <path
                d={`M${CX} 75 V82`}
                fill="none"
                stroke={CREAM}
                strokeWidth={1.8}
            />
            {item.detail !== undefined && <Detail kind={item.detail} />}
        </>
    );
}

function Shoes({ item }: Readonly<{ item: ItemSpec }>) {
    return (
        <>
            <ellipse cx={CX - 14} cy={87} rx={8.5} ry={5} fill={item.color} />
            <ellipse cx={CX + 14} cy={87} rx={8.5} ry={5} fill={item.color} />
            {item.detail !== undefined && <Detail kind={item.detail} />}
        </>
    );
}

function Medal({ item }: Readonly<{ item: ItemSpec }>) {
    return (
        <g data-slot="medal">
            <Stroke
                d={`M${CX - 7} 69 L${CX} 77 L${CX + 7} 69`}
                width={3}
                color={LACE}
            />
            <circle
                cx={CX}
                cy={85}
                r={6}
                fill={item.color}
                stroke={GOLD_INK}
                strokeWidth={1.6}
            />
            {item.detail !== undefined && <Detail kind={item.detail} />}
        </g>
    );
}

function Aura({ color, dash }: Readonly<{ color: string; dash: string }>) {
    return (
        <circle
            data-slot="aura"
            cx={CX}
            cy={CY}
            r={AURA_R}
            fill="none"
            stroke={color}
            strokeWidth={2.4}
            strokeDasharray={dash}
            strokeLinecap="round"
            opacity={0.85}
        />
    );
}

function SeasonCoverage({ phase }: Readonly<{ phase: SeasonPhase }>) {
    const config = SEASON_COVERAGE[phase];
    return (
        <>
            {config.angles.map((angle, i) => (
                <ellipse
                    key={angle}
                    cx={CX}
                    cy={CY}
                    rx={BODY_R}
                    ry={11 + i * 3}
                    fill="none"
                    stroke={SEASON_COLORS[i % SEASON_COLORS.length]}
                    strokeWidth={config.width}
                    opacity={config.opacity}
                    transform={`rotate(${angle} ${CX} ${CY})`}
                />
            ))}
            {config.shine === true && (
                <ellipse
                    data-season="shine"
                    cx={CX - 8}
                    cy={CY - 12}
                    rx={14}
                    ry={9}
                    fill="#fffaf0"
                    opacity={0.45}
                    transform={`rotate(-24 ${CX - 8} ${CY - 12})`}
                />
            )}
        </>
    );
}

// ── Helpers ──────────────────────────────────────────────────────────

function resolveAuraKey(equipped: TemariEquipped | null): string | null {
    if (!equipped?.aura) return null;
    if (typeof equipped.aura === 'string') return equipped.aura;
    return 'warmup';
}

function itemFor(
    table: Record<string, ItemSpec>,
    key: string | null | undefined,
    fallback: string,
): ItemSpec | null {
    if (key === null || key === undefined) return null;
    return table[key] ?? table[fallback];
}

// ── Main component ───────────────────────────────────────────────────

function TemariProto({
    pose = 'proud',
    size = 140,
    tone = 'cream',
    equipped = null,
    animate = false,
    dropShadow = true,
    seasonPhase,
    className,
}: Readonly<TemariProtoProps>) {
    const aspectHeight = (size * VIEW_H) / VIEW_W;

    const expression = POSE_TO_EXPRESSION[pose];
    const spec = EXPRESSION_SPEC[expression];
    const halo = HALO[spec.halo];
    const [browOuter, browInner] = spec.brow;
    const [browROuter, browRInner] = spec.browR ?? spec.brow;

    const headband = itemFor(HEADBAND_ITEMS, equipped?.headband, 'uncommon');
    const shirt = itemFor(SHIRT_ITEMS, equipped?.shirt, 'beginner');
    const shorts = itemFor(SHORTS_ITEMS, equipped?.shorts, 'lightweight');
    const shoes = itemFor(SHOES_ITEMS, equipped?.shoes, 'basic');
    const medal =
        !equipped?.medal || equipped.medal === 'none'
            ? null
            : itemFor(MEDAL_ITEMS, equipped.medal, 'first');

    const auraKey = resolveAuraKey(equipped);
    const aura =
        auraKey === null ? null : (AURA_ITEMS[auraKey] ?? AURA_ITEMS.warmup);

    // Several instances render on one page (the accessory catalogue grid), so
    // the clip needs a per-instance id even though the geometry is identical.
    const clipId = `temari-body-clip-${useId()}`;

    let rootAnim: CSSProperties['animation'] = 'none';
    if (animate !== false) {
        rootAnim = typeof animate === 'string' ? animate : POSE_ANIM[pose];
    }

    const character = (
        <g transform={PLACE_TRANSFORM}>
            {aura !== null && <Aura color={aura.color} dash={aura.dash} />}
            <circle
                data-part="halo"
                cx={CX}
                cy={CY}
                r={HALO_R}
                fill="none"
                stroke={halo.color}
                strokeWidth={halo.width}
            />
            {shoes !== null && <Shoes item={shoes} />}
            <circle
                data-part="body"
                cx={CX}
                cy={CY}
                r={BODY_R}
                fill={CREAM}
                stroke={tone === 'sky' ? CREAM : SKY}
                strokeWidth={4.5}
            />
            <g clipPath={`url(#${clipId})`}>
                {seasonPhase !== undefined && (
                    <SeasonCoverage phase={seasonPhase} />
                )}
                {headband !== null && <Headband item={headband} />}
                {shirt !== null && <Shirt item={shirt} />}
                {shorts !== null && <Shorts item={shorts} />}
            </g>
            {medal !== null && <Medal item={medal} />}
            <Brow x={EYE_L} outerY={browOuter} innerY={browInner} side="l" />
            <Brow x={EYE_R} outerY={browROuter} innerY={browRInner} side="r" />
            <Eyes shape={spec.eyes} />
            <Mouth shape={spec.mouth} />
        </g>
    );

    return (
        <div
            className={cn('temari-root', className)}
            style={{ animation: rootAnim, width: size, height: aspectHeight }}
            data-pose={pose}
            data-expression={expression}
            data-tone={tone}
        >
            <svg
                viewBox={`0 ${VIEW_Y} ${VIEW_W} ${VIEW_H}`}
                width={size}
                height={aspectHeight}
                style={{ display: 'block', overflow: 'visible' }}
                aria-hidden
            >
                <defs>
                    <clipPath id={clipId}>
                        <circle cx={CX} cy={CY} r={CLIP_R} />
                    </clipPath>
                    {dropShadow && (
                        <filter
                            id="temari-shadow"
                            x="-20%"
                            y="-10%"
                            width="140%"
                            height="140%"
                        >
                            <feDropShadow
                                dx="0"
                                dy="3"
                                stdDeviation="3"
                                floodColor="#3b2f1f"
                                floodOpacity="0.15"
                            />
                        </filter>
                    )}
                </defs>
                {dropShadow ? (
                    <g filter="url(#temari-shadow)">{character}</g>
                ) : (
                    character
                )}
            </svg>
        </div>
    );
}

/**
 * Field-level comparison so a parent that re-renders with a fresh inline
 * `equipped={{...}}` object doesn't force this SVG tree to rebuild.
 */
function equippedEqual(
    a: TemariEquipped | null,
    b: TemariEquipped | null,
): boolean {
    if (a === b) {
        return true;
    }
    if (a === null || b === null) {
        return false;
    }
    return (
        a.headband === b.headband &&
        a.medal === b.medal &&
        a.shirt === b.shirt &&
        a.shorts === b.shorts &&
        a.shoes === b.shoes &&
        a.aura === b.aura
    );
}

function propsEqual(
    a: Readonly<TemariProtoProps>,
    b: Readonly<TemariProtoProps>,
): boolean {
    return (
        a.pose === b.pose &&
        a.size === b.size &&
        a.tone === b.tone &&
        a.animate === b.animate &&
        a.dropShadow === b.dropShadow &&
        a.seasonPhase === b.seasonPhase &&
        a.className === b.className &&
        equippedEqual(a.equipped ?? null, b.equipped ?? null)
    );
}

export default memo(TemariProto, propsEqual);
